class NumArray {
    int[] tree;
    int n;
    public NumArray(int[] nums) {
        n = nums.length;
        tree = new int[2 * n];
        for (int i = 0; i < n; i++) tree[n + i] = nums[i];
        for (int i = n - 1; i > 0; i--) tree[i] = tree[2 * i] + tree[2 * i + 1];
    }
    public void update(int index, int val) {
        index += n;
        tree[index] = val;
        for (index /= 2; index >= 1; index /= 2) {
            tree[index] = tree[2 * index] + tree[2 * index + 1];
        }
    }
    public int sumRange(int left, int right) {
        int sum = 0;
        for (left += n, right += n + 1; left < right; left /= 2, right /= 2) {
            if ((left & 1) != 0) sum += tree[left++];
            if ((right & 1) != 0) sum += tree[--right];
        }
        return sum;
    }
}

class SegmentTree {
    int[] tree;
    int n;
    public SegmentTree(int[] nums) {
        n = nums.length;
        tree = new int[4 * n];
        build(nums, 0, 0, n - 1);
    }
    private void build(int[] nums, int node, int start, int end) {
        if (start == end) {
            tree[node] = nums[start];
        } else {
            int mid = start + (end - start) / 2;
            build(nums, 2 * node + 1, start, mid);
            build(nums, 2 * node + 2, mid + 1, end);
            tree[node] = Math.min(tree[2 * node + 1], tree[2 * node + 2]);
        }
    }
    public void update(int idx, int val) {
        update(0, 0, n - 1, idx, val);
    }
    private void update(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = val;
        } else {
            int mid = start + (end - start) / 2;
            if (idx <= mid) update(2 * node + 1, start, mid, idx, val);
            else update(2 * node + 2, mid + 1, end, idx, val);
            tree[node] = Math.min(tree[2 * node + 1], tree[2 * node + 2]);
        }
    }
    public int query(int L, int R) {
        return query(0, 0, n - 1, L, R);
    }
    private int query(int node, int start, int end, int L, int R) {
        if (R < start || L > end) return Integer.MAX_VALUE; // No overlap
        if (L <= start && end <= R) return tree[node]; // Total overlap
        int mid = start + (end - start) / 2;
        int leftMin = query(2 * node + 1, start, mid, L, R);
        int rightMin = query(2 * node + 2, mid + 1, end, L, R);
        return Math.min(leftMin, rightMin);
    }
}

class LazySegmentTree {
    int[] tree, lazy;
    int n;
    public LazySegmentTree(int[] nums) {
        n = nums.length;
        tree = new int[4 * n];
        lazy = new int[4 * n];
        build(nums, 0, 0, n - 1);
    }
    private void build(int[] nums, int node, int start, int end) {
        if (start == end) { tree[node] = nums[start]; }
        else {
            int mid = start + (end - start) / 2;
            build(nums, 2 * node + 1, start, mid);
            build(nums, 2 * node + 2, mid + 1, end);
            tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
        }
    }
    private void push(int node, int start, int end) {
        if (lazy[node] != 0) {
            tree[node] += (end - start + 1) * lazy[node];
            if (start != end) {
                lazy[2 * node + 1] += lazy[node];
                lazy[2 * node + 2] += lazy[node];
            }
            lazy[node] = 0;
        }
    }
    public void updateRange(int L, int R, int val) {
        updateRange(0, 0, n - 1, L, R, val);
    }
    private void updateRange(int node, int start, int end, int L, int R, int val) {
        push(node, start, end);
        if (start > end || start > R || end < L) return;
        if (start >= L && end <= R) {
            lazy[node] += val;
            push(node, start, end);
            return;
        }
        int mid = start + (end - start) / 2;
        updateRange(2 * node + 1, start, mid, L, R, val);
        updateRange(2 * node + 2, mid + 1, end, L, R, val);
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
    }
    public int queryRange(int L, int R) {
        return queryRange(0, 0, n - 1, L, R);
    }
    private int queryRange(int node, int start, int end, int L, int R) {
        if (start > end || start > R || end < L) return 0;
        push(node, start, end);
        if (start >= L && end <= R) return tree[node];
        int mid = start + (end - start) / 2;
        return queryRange(2 * node + 1, start, mid, L, R) + queryRange(2 * node + 2, mid + 1, end, L, R);
    }
}

class DynamicSegmentTree {
    class Node {
        Node left, right;
        int val, lazy;
    }
    Node root;
    int minRange, maxRange;
    public DynamicSegmentTree(int min, int max) {
        root = new Node();
        minRange = min;
        maxRange = max;
    }
    public void update(int L, int R, int val) {
        update(root, minRange, maxRange, L, R, val);
    }
    private void update(Node node, int start, int end, int L, int R, int val) {
        if (L <= start && end <= R) {
            node.val += (end - start + 1) * val;
            node.lazy += val;
            return;
        }
        int mid = start + (end - start) / 2;
        push(node, start, end, mid);
        if (L <= mid) update(node.left, start, mid, L, R, val);
        if (R > mid) update(node.right, mid + 1, end, L, R, val);
        node.val = node.left.val + node.right.val;
    }
    private void push(Node node, int start, int end, int mid) {
        if (node.left == null) node.left = new Node();
        if (node.right == null) node.right = new Node();
        if (node.lazy != 0) {
            node.left.val += (mid - start + 1) * node.lazy;
            node.left.lazy += node.lazy;
            node.right.val += (end - mid) * node.lazy;
            node.right.lazy += node.lazy;
            node.lazy = 0;
        }
    }
    public int query(int L, int R) {
        return query(root, minRange, maxRange, L, R);
    }
    private int query(Node node, int start, int end, int L, int R) {
        if (node == null || start > R || end < L) return 0;
        if (L <= start && end <= R) return node.val;
        int mid = start + (end - start) / 2;
        push(node, start, end, mid);
        return query(node.left, start, mid, L, R) + query(node.right, mid + 1, end, L, R);
    }
}

class MergeSortTree {
    List<List<Integer>> tree;
    int n;
    public MergeSortTree(int[] nums) {
        n = nums.length;
        tree = new ArrayList<>(4 * n);
        for (int i = 0; i < 4 * n; i++) tree.add(new ArrayList<>());
        build(nums, 0, 0, n - 1);
    }
    private void build(int[] nums, int node, int start, int end) {
        if (start == end) {
            tree.get(node).add(nums[start]);
        } else {
            int mid = start + (end - start) / 2;
            build(nums, 2 * node + 1, start, mid);
            build(nums, 2 * node + 2, mid + 1, end);
            merge(tree.get(node), tree.get(2 * node + 1), tree.get(2 * node + 2));
        }
    }
    private void merge(List<Integer> res, List<Integer> left, List<Integer> right) {
        int i = 0, j = 0;
        while (i < left.size() && j < right.size()) {
            if (left.get(i) < right.get(j)) res.add(left.get(i++));
            else res.add(right.get(j++));
        }
        while (i < left.size()) res.add(left.get(i++));
        while (j < right.size()) res.add(right.get(j++));
    }
    public int query(int L, int R, int X) {
        return query(0, 0, n - 1, L, R, X);
    }
    private int query(int node, int start, int end, int L, int R, int X) {
        if (R < start || L > end) return 0;
        if (L <= start && end <= R) {
            // Count elements strictly greater than X
            int idx = Collections.binarySearch(tree.get(node), X);
            if (idx < 0) idx = -idx - 1;
            else idx++; // if X is found, elements greater than X start from idx+1
            return tree.get(node).size() - idx;
        }
        int mid = start + (end - start) / 2;
        return query(2 * node + 1, start, mid, L, R, X) + query(2 * node + 2, mid + 1, end, L, R, X);
    }
}
